             MockedStatic<Eventos> eventosMock = mockStatic(Eventos.class)) {

            xmlNfeUtilMock.when(() -> XmlNfeUtil.objectToXml(enviEvento, "ISO-8859-1"))
                .thenReturn(originalXml);

            eventosMock.when(() -> Eventos.enviarEvento(
                eq(config), 
                eq(expectedCleanedXml), 
                eq(ServicosEnum.CANC_ECONF), 
                eq(true), 
                eq(true), 
                eq(DocumentoEnum.NFE)
            )).thenReturn(resultXml);

            xmlNfeUtilMock.when(() -> XmlNfeUtil.xmlToObject(resultXml, TRetEnvEvento.class))
                .thenReturn(expectedRetEnvEvento);

